css:
/* ------------------------------------------------------------ CONTACT CTA ---
   The handoff sets this band on --color-ink (#242424), which is its primary
   text colour rather than the near-black used for the header and footer, so
   the value is written out here rather than taken from the ink token. */

[data-bz-node="contact-band"]{
  background:#242424;
  padding:100px 48px;
  text-align:center;
}
[data-bz-node="contact-band"] .bz-block{padding-block:0;}
[data-bz-node="contact-row"]{max-width:560px;margin-inline:auto;}
[data-bz-node="contact-heading"] h2{
  font:800 var(--text-h2-sm,34px)/1.6 var(--font-heading);
  color:#fff;margin:0 0 14px;
}
[data-bz-node="contact-body"] .bz-text{max-width:none;}
[data-bz-node="contact-body"]{margin-bottom:36px;}
[data-bz-node="contact-body"] p{
  font-size:var(--text-base,15px);line-height:1.6;color:#C7C1B4;margin:0;
}
[data-bz-node="contact-buttons"] .bz-btns{justify-content:center;}
[data-bz-node="contact-note"]{margin-top:20px;}
[data-bz-node="contact-note"] .bz-text{max-width:none;}
[data-bz-node="contact-note"] p{font-size:13px;line-height:1.6;color:#B0B0B0;margin:0;}
@media (max-width:640px){
  [data-bz-node="contact-band"]{padding:56px 20px;}
  [data-bz-node="contact-heading"] h2{font-size:26px;}
}
